from quilldown_spec import MathInline


def test_load_json_mathinline():
    json_data = r"""
    {
      "kind": "math",
      "latex": "sample",
      "display": true
    }
    """
    data = json.loads(json_data, strict=False)
    instance = MathInline.load(data)
    assert instance is not None
    assert instance.kind == "math"
    assert instance.latex == "sample"
    assert instance.display


