def test_roundtrip_json_mathinline():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "kind": "math",
      "latex": "sample",
      "display": true
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = MathInline.load(original_data)
    saved_data = instance.save()
    reloaded = MathInline.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "math"
    assert reloaded.latex == "sample"
    assert reloaded.display


